#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/VISUAL_ALIGNMENT_1.md ]] || { echo 'Run from your repository root after applying the first Android visual-alignment update.' >&2; exit 1; }
python3 - <<'VISUAL_GROUP_TWO'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/lib/local_media_index.dart': '',
'desktop/hyper_player/lib/screens/library_screens.dart': '',
'desktop/hyper_player/lib/screens/desktop_display_screen.dart': '',
'desktop/hyper_player/test/library_screens_test.dart': '',
'desktop/hyper_player/VISUAL_ALIGNMENT_2.md': '',
}
for name, data in files.items():
    p = Path(name)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(data))
print('Audio, Folders and Display Settings Windows visual-alignment update applied. Android unchanged.')
VISUAL_GROUP_TWO
